  "'CHAT = re.compile(r\"[0-9a-f-]{36}\")',",
  "'ASK_TIMEOUT = 10',",
  "'ROLLOUTS = 200',",
  "'FIRST_LINE = 1 << 20',",
  "'DECISIONS = {\"allow\": \"allow\", \"prompt\": \"ask\", \"forbidden\": \"deny\"}',",
  "'CODEX_KINDS = {\"stdio\": \"stdio\", \"streamable_http\": \"http\"}',",
  "'OFF = \"off\"',",
  "'NOT_PLAIN = object()',",
  "'AGENT_OFF = re.compile(r\"Agent\\\\(([\\\\w.:-]{1,80})\\\\)\")',",
  "'EFFORT_ENV = \"CLAUDE_CODE_EFFORT_LEVEL\"',",
  "'def read_text(path, largest=LARGEST):',",
